package main

import (
  "fmt"
  "io/fs"

  "gopkg.in/yaml.v3"
)

type ServerConfig struct {
  Addr string `yaml:"addr"`
}

type GitConfig struct {
  RepoPath string `yaml:"repo_path"`
}

type Config struct {
  Server ServerConfig `yaml:"server"`
  Git    GitConfig    `yaml:"git"`
}

func LoadFS(fsys fs.FS, name string) (*Config, error) {
  f, err := fsys.Open(name)
  if err != nil {
    return nil, err
  }
  defer f.Close()
  var cfg Config
  if err := yaml.NewDecoder(f).Decode(&cfg); err != nil {
    return nil, err
  }
  if cfg.Server.Addr == "" {
    return nil, fmt.Errorf("server.addr is required")
  }
  return &cfg, nil
}

package main

import (
  "net/http"

  "github.com/go-chi/chi/v5"
)

func NewRouter() http.Handler {
  r := chi.NewRouter()
  r.Get("/healthz", func(w http.ResponseWriter, _ *http.Request) {
    w.WriteHeader(http.StatusOK)
    _, _ = w.Write([]byte("ok"))
  })
  return r
}

package main

import (
  "flag"
  "fmt"
  "os"
)

func main() {
  cfgPath := flag.String("config", "config.example.yaml", "path to YAML config")
  flag.Parse()
  cfg, err := LoadFS(os.DirFS("."), *cfgPath)
  if err != nil {
    fmt.Fprintf(os.Stderr, "config: %v\n", err)
    os.Exit(1)
  }
  _ = NewRouter()
  fmt.Printf("storyforge backend config loaded addr=%s repo=%s\n", cfg.Server.Addr, cfg.Git.RepoPath)
}
